const fs = require('fs');

const source = fs.readFileSync('README.md', 'utf8');
const headings = source
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'));

fs.writeFileSync('INDEX.md', headings.join('\n') + '\n');

